/** Landing-page copy in the languages riders speak. Keys are shared; `en` is the reference. */

export type Lang = 'en' | 'fr' | 'de' | 'es' | 'pt' | 'it' | 'nl'
export const LANGS: Lang[] = ['en', 'fr', 'de', 'es', 'pt', 'it', 'nl']
export const LANG_NAMES: Record<Lang, string> = { en: 'English', fr: 'Français', de: 'Deutsch', es: 'Español', pt: 'Português', it: 'Italiano', nl: 'Nederlands' }

export function pickLang(path: string, query: string | null, acceptLanguage: string | null): Lang {
  const fromPath = path.replace(/^\//, '').slice(0, 2).toLowerCase()
  if (path.length === 3 && (LANGS as string[]).includes(fromPath)) return fromPath as Lang
  if (query && (LANGS as string[]).includes(query.toLowerCase())) return query.toLowerCase() as Lang
  for (const part of (acceptLanguage ?? '').split(',')) {
    const code = part.trim().slice(0, 2).toLowerCase()
    if ((LANGS as string[]).includes(code)) return code as Lang
  }
  return 'en'
}

